import { fmt } from "./parseItem";

const SANS = "Unbounded, system-ui, -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif";
const MONO = "Geist Mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";

// Typography System
const TYPE = {
  h1: { size: 64, weight: 900, spacing: "-0.02em" },
  h1_compact: { size: 84, weight: 900, spacing: "-0.02em" },
  price: { size: 92, weight: 900 },
  price_compact: { size: 128, weight: 900 },
  label: { size: 11, weight: 800, spacing: "0.1em" },
  sub: { size: 14, weight: 800, spacing: "0.05em" },
  body: { size: 16, weight: 600 },
};

function themeColors() {
  const isDark = document.documentElement.classList.contains("dark");
  return {
    isDark,
    bg: isDark ? "#09090b" : "#efe7d9",
    surface: isDark ? "#18181b" : "#e1d5c2",
    text: isDark ? "#fafafa" : "#1b1814",
    muted: isDark ? "#a1a1aa" : "#5f574f",
    subtle: isDark ? "#52525b" : "#6b6259",
    accent: isDark ? "#10b981" : "#059669",
    accentSoft: isDark ? "#064e3b" : "#dcfce7",
    warning: isDark ? "#f59e0b" : "#d97706",
    error: isDark ? "#ef4444" : "#dc2626",
    border: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.12)",
    grid: isDark ? "rgba(255,255,255,0.03)" : "rgba(0,0,0,0.04)",
    glowPrimary: isDark ? "rgba(16,185,129,0.12)" : "rgba(16,185,129,0.1)",
    glowSecondary: isDark ? "rgba(245,158,11,0.08)" : "rgba(245,158,11,0.06)",
  };
}

const VARIANTS = {
  item: { width: 1200, height: 630, compose: composeItemCard },
  compact: { width: 1080, height: 1080, compose: composeCompactCard },
};

export const EXPORT_VARIANTS = Object.keys(VARIANTS);

function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function fillRoundRect(ctx, x, y, w, h, r, fill, stroke = null) {
  roundRect(ctx, x, y, w, h, r);
  ctx.fillStyle = fill;
  ctx.fill();
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

function drawLabel(ctx, text, x, y, color) {
  ctx.font = `${TYPE.label.weight} ${TYPE.label.size}px ${MONO}`;
  ctx.letterSpacing = TYPE.label.spacing;
  ctx.fillStyle = color;
  ctx.fillText(String(text || "").toUpperCase(), x, y);
  ctx.letterSpacing = "normal";
}

function drawTextLines(ctx, text, x, y, maxWidth, lineHeight, maxLines) {
  const words = String(text || "").split(/\s+/).filter(Boolean);
  const lines = [];
  let line = "";
  let consumed = 0;
  for (const word of words) {
    const next = line ? `${line} ${word}` : word;
    if (ctx.measureText(next).width <= maxWidth || !line) {
      line = next;
      consumed += 1;
      continue;
    }
    lines.push(line);
    line = word;
    consumed += 1;
    if (lines.length >= maxLines) break;
  }
  if (line && lines.length < maxLines) lines.push(line);
  const lastIndex = lines.length - 1;
  // Ellipsis when content was cut — or when a single unbroken word overflows
  // its column (no spaces to wrap on), which would otherwise overprint.
  if (lines.length === maxLines && (consumed < words.length || (lastIndex >= 0 && ctx.measureText(lines[lastIndex]).width > maxWidth))) {
    let last = lines[lines.length - 1];
    while (ctx.measureText(`${last}...`).width > maxWidth && last.length > 1) {
      last = last.slice(0, -1);
    }
    lines[lines.length - 1] = `${last}...`;
  }
  lines.forEach((value, index) => ctx.fillText(value, x, y + index * lineHeight));
  return lines.length * lineHeight;
}

// Title renderer that scales down to fit instead of truncating: tries the
// base size first, then shrinks until the full name fits on two lines.
// Ellipsis is the last resort at the minimum size. Returns drawn height.
function drawFitTitle(ctx, text, x, y, maxWidth, baseLineHeight, baseSize, minSize) {
  const words = String(text || "Unknown Item").split(/\s+/).filter(Boolean);
  ctx.letterSpacing = "-0.02em";
  const wrap = (size) => {
    ctx.font = `900 ${size}px ${SANS}`;
    const lines = [];
    let line = "";
    for (const word of words) {
      const next = line ? `${line} ${word}` : word;
      if (ctx.measureText(next).width <= maxWidth || !line) line = next;
      else { lines.push(line); line = word; }
    }
    if (line) lines.push(line);
    return lines;
  };
  let size = baseSize;
  let lines = wrap(size);
  while (
    size > minSize &&
    (lines.length > 2 || lines.some((value) => ctx.measureText(value).width > maxWidth))
  ) {
    size -= 4;
    lines = wrap(size);
  }
  if (lines.length > 2 || lines.some((value) => ctx.measureText(value).width > maxWidth)) {
    lines = lines.slice(0, 2);
    let last = lines[1] || "";
    while (ctx.measureText(`${last}...`).width > maxWidth && last.length > 1) {
      last = last.slice(0, -1);
    }
    lines[1] = `${last}...`;
  }
  ctx.font = `900 ${size}px ${SANS}`;
  const lineHeight = (baseLineHeight * size) / baseSize;
  lines.forEach((value, index) => ctx.fillText(value, x, y + index * lineHeight));
  ctx.letterSpacing = "normal";
  return lines.length * lineHeight;
}

function drawChip(ctx, text, x, y, color, bg, border) {
  ctx.font = `800 18px ${MONO}`;
  const width = Math.ceil(ctx.measureText(text).width) + 18;
  fillRoundRect(ctx, x, y - 22, width, 30, 4, bg, border);
  ctx.fillStyle = color;
  ctx.fillText(text, x + 9, y);
  return width;
}

function drawGrid(ctx, width, height, color) {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  const size = 40;
  for (let x = 0; x <= width; x += size) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }
  for (let y = 0; y <= height; y += size) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
    ctx.stroke();
  }
  ctx.restore();
}

function drawGlow(ctx, x, y, radius, color, width, height) {
  const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
  gradient.addColorStop(0, color);
  gradient.addColorStop(1, "transparent");
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function fmtStamp(ms) {
  const d = new Date(ms || Date.now());
  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mi = String(d.getUTCMinutes()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd} ${hh}:${mi} UTC`;
}

function trendLabel(trend, t) {
  if (trend === "up") return { label: "Rising", color: t.accent };
  if (trend === "down") return { label: "Falling", color: t.error };
  return { label: "Stable", color: t.subtle };
}

// Image loader with a hard timeout so a stalled remote asset can never
// hang an export. Resolves null on any failure (caller draws fallback).
function loadImage(url, timeoutMs = 6000) {
  return new Promise((resolve) => {
    if (!url) { resolve(null); return; }
    let done = false;
    const finish = (value) => { if (!done) { done = true; resolve(value); } };
    const timer = setTimeout(() => finish(null), timeoutMs);
    const img = new Image();
    img.onload = () => { clearTimeout(timer); finish(img); };
    img.onerror = () => { clearTimeout(timer); finish(null); };
    img.src = url;
  });
}

function drawSparkline(ctx, series, median, x, y, w, h, t) {
  fillRoundRect(ctx, x, y, w, h, 12, t.surface, t.border);
  const data = Array.isArray(series) ? series.filter((p) => Number(p?.v) > 0) : [];
  if (data.length < 2) {
    ctx.font = `700 13px ${MONO}`;
    ctx.fillStyle = t.subtle;
    ctx.textAlign = "center";
    ctx.fillText(data.length === 1 ? "1 DATA POINT" : "INSUFFICIENT DATA", x + w / 2, y + h / 2);
    ctx.textAlign = "left";
    return;
  }

  const padL = 64;
  const padR = 32;
  const padT = 40;
  const padB = 48;
  const innerW = w - padL - padR;
  const innerH = h - padT - padB;
  const values = data.map((p) => Number(p.v));
  let min = Math.min(...values, Number(median || Infinity));
  let max = Math.max(...values, Number(median || 0));
  const span = max - min || 1;
  min -= span * 0.1;
  max += span * 0.1;
  const range = max - min || 1;

  const points = data.map((p, index) => [
    x + padL + (innerW * index) / (data.length - 1),
    y + padT + innerH - ((Number(p.v) - min) / range) * innerH,
  ]);

  ctx.save();
  ctx.strokeStyle = t.border;
  ctx.fillStyle = t.muted;
  ctx.font = `500 10px ${MONO}`;
  
  // Grid lines
  [min, min + range / 2, max].forEach((tick) => {
    const ty = y + padT + innerH - ((tick - min) / range) * innerH;
    ctx.beginPath();
    ctx.moveTo(x + padL, ty);
    ctx.lineTo(x + padL + innerW, ty);
    ctx.stroke();
    ctx.textAlign = "right";
    ctx.fillText(fmt(tick), x + padL - 12, ty + 3);
  });
  ctx.textAlign = "left";

  if (median > 0) {
    const medianY = y + padT + innerH - ((median - min) / range) * innerH;
    ctx.strokeStyle = t.warning;
    ctx.setLineDash([4, 4]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + padL, medianY);
    ctx.lineTo(x + padL + innerW, medianY);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // Area fill
  ctx.beginPath();
  points.forEach(([px, py], index) => {
    if (index === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  });
  const last = points[points.length - 1];
  const first = points[0];
  ctx.lineTo(last[0], y + padT + innerH);
  ctx.lineTo(first[0], y + padT + innerH);
  ctx.closePath();
  const fill = ctx.createLinearGradient(0, y + padT, 0, y + padT + innerH);
  fill.addColorStop(0, t.accent + "33");
  fill.addColorStop(1, "transparent");
  ctx.fillStyle = fill;
  ctx.fill();

  // Line
  ctx.beginPath();
  points.forEach(([px, py], index) => {
    if (index === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  });
  ctx.strokeStyle = t.accent;
  ctx.lineWidth = 2.5;
  ctx.lineJoin = "round";
  ctx.lineCap = "round";
  ctx.stroke();

  // Points
  const lastP = points[points.length - 1];
  ctx.fillStyle = t.accent;
  ctx.beginPath();
  ctx.arc(lastP[0], lastP[1], 4.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = t.surface;
  ctx.lineWidth = 2;
  ctx.stroke();

  // Date labels (mid label only when there is room for it)
  const labelDate = (p) => new Date(p.ts || p.t || Date.now()).toLocaleDateString(undefined, { month: "short", day: "numeric" });
  ctx.fillStyle = t.subtle;
  ctx.font = `600 10px ${MONO}`;
  ctx.textAlign = "center";
  ctx.fillText(labelDate(data[0]), points[0][0], y + h - 16);
  if (data.length >= 3) {
    ctx.fillText(labelDate(data[Math.floor(data.length / 2)]), points[Math.floor(points.length / 2)][0], y + h - 16);
  }
  ctx.fillText(labelDate(data[data.length - 1]), lastP[0], y + h - 16);
  ctx.restore();
}

function drawTopSellers(ctx, sellers, y, t, maxWidth = 1088) {
  const xStart = 56;
  drawLabel(ctx, "Latest sellers", xStart, y, t.muted);
  const list = Array.isArray(sellers) ? sellers.slice(0, 3) : [];
  if (list.length === 0) {
    ctx.font = `600 14px ${SANS}`;
    ctx.fillStyle = t.subtle;
    ctx.fillText("No active listings recorded.", xStart, y + 44);
    return;
  }

  const gutter = 12;
  const availableW = maxWidth - xStart - 56;
  const cardW = (availableW - (list.length - 1) * gutter) / list.length;
  
  list.forEach((seller, index) => {
    const x = xStart + index * (cardW + gutter);
    fillRoundRect(ctx, x, y + 18, cardW, 64, 10, t.surface, t.border);
    ctx.font = `800 11px ${MONO}`;
    ctx.fillStyle = t.subtle;
    ctx.fillText(`#${index + 1}`, x + 16, y + 55);

    // Two-zone layout: price is measured first and always wins ties, so
    // long names truncate instead of colliding with large prices.
    ctx.font = `900 17px ${MONO}`;
    const priceText = fmt(seller.unitPrice || 0);
    const priceWidth = Math.ceil(ctx.measureText(priceText).width);
    const priceRight = x + cardW - 16;
    const nameX = x + 48;
    const nameMaxWidth = Math.max(40, priceRight - priceWidth - 20 - nameX);
    ctx.font = `800 15px ${SANS}`;
    ctx.fillStyle = t.text;
    drawTextLines(ctx, seller.name || "Unknown", nameX, y + 43, nameMaxWidth, 16, 1);

    const labelMap = { Trustworthy: "Market-aligned", Neutral: "Mixed pricing", Suspicious: "Frequently above range", Flagged: "Strongly above range" };
    const label = labelMap[seller.label] || seller.label || "Mixed pricing";
    const labelColor = label === "Market-aligned" ? t.accent : label === "Frequently above range" ? t.warning : label === "Strongly above range" ? t.error : t.muted;
    ctx.font = `700 9px ${MONO}`;
    ctx.fillStyle = labelColor;
    ctx.fillText(label.toUpperCase(), nameX, y + 63);

    ctx.font = `900 17px ${MONO}`;
    ctx.fillStyle = t.accent;
    ctx.textAlign = "right";
    ctx.fillText(priceText, priceRight, y + 56);
    ctx.textAlign = "left";
  });
}

function drawItemArt(ctx, art, x, y, size, t) {
  fillRoundRect(ctx, x, y, size, size, 16, t.surface, t.border);
  if (!art?.el) {
    ctx.font = `900 ${Math.round(size * 0.36)}px ${SANS}`;
    ctx.fillStyle = t.subtle;
    ctx.textAlign = "center";
    ctx.fillText("?", x + size / 2, y + size / 2 + size * 0.13);
    ctx.textAlign = "left";
    return;
  }
  const inset = 14;
  const wasSmooth = ctx.imageSmoothingEnabled;
  if (art.pixelated) ctx.imageSmoothingEnabled = false;
  try {
    ctx.drawImage(art.el, x + inset, y + inset, size - inset * 2, size - inset * 2);
  } catch {
    /* corrupt image data — panel fallback already drawn */
  }
  ctx.imageSmoothingEnabled = wasSmooth;
}

function drawHeader(ctx, data, width, t) {
  ctx.save();
  ctx.font = `900 12px ${MONO}`;
  ctx.fillStyle = t.accent;
  ctx.beginPath();
  ctx.arc(62, 46, 4, 0, Math.PI * 2);
  ctx.fill();
  
  ctx.fillText("CMI SNAPSHOT", 74, 50);
  
  ctx.fillStyle = t.subtle;
  ctx.textAlign = "right";
  ctx.font = `700 11px ${MONO}`;
  ctx.fillText(fmtStamp(data.generatedAt), width - 56, 50);
  ctx.restore();
}

function drawFooter(ctx, width, height, t) {
  ctx.save();
  ctx.font = `800 10px ${MONO}`;
  ctx.fillStyle = t.subtle;
  ctx.fillText("CASTIA MARKET INSIGHT", 56, height - 12);
  
  ctx.textAlign = "right";
  ctx.fillStyle = t.muted;
  ctx.fillText("DATA AGGREGATED BY LEKTO_", width - 56, height - 12);
  ctx.restore();
}

function composeItemCard(ctx, data, width, height, art) {
  const t = themeColors();
  drawHeader(ctx, data, width, t);

  // Hero Section — artwork panel left, title block right (media object).
  const category = `${data.category || "General"}${data.tier > 0 ? ` · TIER ${data.tier}` : ""}`;
  drawLabel(ctx, category, 56, 100, t.accent);
  drawItemArt(ctx, art, 56, 122, 160, t);

  ctx.fillStyle = t.text;
  const titleHeight = drawFitTitle(ctx, data.name, 240, 155, 360, 62, 64, 40);

  let chipX = 240;
  const chipY = 175 + Math.min(titleHeight, 124);
  if (data.tier > 0) {
    chipX += drawChip(ctx, `T${data.tier}`, chipX, chipY, t.warning, t.warning + "1A", t.warning + "33") + 10;
  }
  for (const modifier of (data.modifiers || []).slice(0, 3)) {
    chipX += drawChip(ctx, String(modifier).toUpperCase(), chipX, chipY, t.accent, t.accent + "1A", t.accent + "33") + 10;
  }

  // Benchmark Stats
  const statsY = 320;
  drawLabel(ctx, "Benchmark Median", 56, statsY, t.muted);
  ctx.font = `${TYPE.price.weight} ${TYPE.price.size}px ${SANS}`;
  ctx.fillStyle = t.accent;
  ctx.fillText(data.median > 0 ? fmt(data.median) : "—", 56, statsY + 90);

  const trend = trendLabel(data.trend, t);
  ctx.font = `900 18px ${MONO}`;
  ctx.fillStyle = trend.color;
  ctx.fillText(trend.label.toUpperCase(), 56, statsY + 125);

  // Sub Stats - tightened to clear the sellers block below
  const subStatsY = statsY + 158;
  ctx.font = `${TYPE.label.weight} ${TYPE.label.size}px ${MONO}`;
  ctx.fillStyle = t.muted;
  ctx.fillText("CONFIDENCE", 56, subStatsY);
  ctx.fillText("SAMPLES", 250, subStatsY);
  
  ctx.font = `800 13px ${MONO}`;
  ctx.fillStyle = data.confidence === "high" || data.confidence === "good" ? t.accent : data.confidence === "fair" ? t.warning : t.subtle;
  ctx.fillText(String(data.confidence || "n/a").toUpperCase(), 56, subStatsY + 22);
  ctx.fillStyle = t.text;
  ctx.fillText(String(data.samples || 0), 250, subStatsY + 22);

  // Price action position
  drawLabel(ctx, `Price action · ${(data.series || []).length} pts`, 620, 100, t.muted);
  drawSparkline(ctx, data.series || [], data.median || 0, 620, 122, 524, 320, t);

  // Sellers - sits below the sub-stats values with room to breathe
  drawTopSellers(ctx, data.topSellers || [], 522, t, width);

  drawFooter(ctx, width, height, t);
}

function composeCompactCard(ctx, data, width, height, art) {
  const t = themeColors();
  drawHeader(ctx, data, width, t);

  const category = `${data.category || "General"}${data.tier > 0 ? ` · TIER ${data.tier}` : ""}`;
  drawLabel(ctx, category, 64, 130, t.accent);
  drawItemArt(ctx, art, 64, 152, 150, t);

  ctx.fillStyle = t.text;
  const titleHeight = drawFitTitle(ctx, data.name, 238, 196, width - 302, 88, 84, 52);

  let chipX = 64;
  const chipY = 220 + Math.min(titleHeight, 176);
  if (data.tier > 0) {
    chipX += drawChip(ctx, `T${data.tier}`, chipX, chipY, t.warning, t.warning + "1A", t.warning + "33") + 10;
  }
  for (const modifier of (data.modifiers || []).slice(0, 3)) {
    chipX += drawChip(ctx, String(modifier).toUpperCase(), chipX, chipY, t.accent, t.accent + "1A", t.accent + "33") + 10;
  }

  const statsY = 420;
  drawLabel(ctx, "Benchmark Median", 64, statsY, t.muted);
  ctx.font = `${TYPE.price_compact.weight} ${TYPE.price_compact.size}px ${SANS}`;
  ctx.fillStyle = t.accent;
  ctx.fillText(data.median > 0 ? fmt(data.median) : "—", 64, statsY + 120);

  const trend = trendLabel(data.trend, t);
  ctx.font = `900 24px ${MONO}`;
  ctx.fillStyle = trend.color;
  ctx.fillText(trend.label.toUpperCase(), 64, statsY + 175);

  const subStatsY = statsY + 230;
  ctx.font = `800 14px ${MONO}`;
  ctx.fillStyle = t.muted;
  ctx.fillText("CONFIDENCE", 64, subStatsY);
  ctx.fillText("SAMPLES", 320, subStatsY);
  ctx.fillStyle = data.confidence === "high" || data.confidence === "good" ? t.accent : data.confidence === "fair" ? t.warning : t.subtle;
  ctx.fillText(String(data.confidence || "n/a").toUpperCase(), 64, subStatsY + 30);
  ctx.fillStyle = t.text;
  ctx.fillText(String(data.samples || 0), 320, subStatsY + 30);

  drawLabel(ctx, `Price action · ${(data.series || []).length} pts`, 64, 700, t.muted);
  drawSparkline(ctx, data.series || [], data.median || 0, 64, 725, width - 128, 200, t);

  const sellersY = 940;
  drawTopSellers(ctx, data.topSellers || [], sellersY, t, width);

  drawFooter(ctx, width, height, t);
}

export async function renderCastiaCardToBlob(data, { variant = "item" } = {}) {
  const v = VARIANTS[variant] || VARIANTS.item;
  // Wait for webfonts so the PNG never bakes in fallback type.
  try { await document.fonts.ready; } catch { /* ignore */ }
  const artEl = await loadImage(data?.imageSrc);
  const art = artEl ? { el: artEl, pixelated: data?.imagePixelated !== false } : null;

  const canvas = document.createElement("canvas");
  canvas.width = v.width;
  canvas.height = v.height;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas is unavailable");

  const t = themeColors();
  ctx.fillStyle = t.bg;
  ctx.fillRect(0, 0, v.width, v.height);

  // Background glows
  if (v.width >= v.height) {
    drawGlow(ctx, v.width - 200, 100, 600, t.glowPrimary, v.width, v.height);
    drawGlow(ctx, 100, v.height - 100, 500, t.glowSecondary, v.width, v.height);
  } else {
    drawGlow(ctx, v.width - 100, 100, 600, t.glowPrimary, v.width, v.height);
    drawGlow(ctx, 100, v.height - 200, 500, t.glowSecondary, v.width, v.height);
  }

  drawGrid(ctx, v.width, v.height, t.grid);

  await v.compose(ctx, data, v.width, v.height, art);

  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("PNG export failed"));
    }, "image/png");
  });
}
