/** Complete Oxywire equipment profiles are distinct from legacy unknown variants. */
export function runeTags(variantKey, enchantments) {
  if (!String(variantKey || "").startsWith("oxy2:")) return [];
  return Object.entries(enchantments || {})
    .filter(([id, level]) => id.startsWith("oxywire:") && Number.isInteger(level) && level > 0)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([id, level]) => {
      const raw = id.slice("oxywire:".length).replace(/_/g, " ")
        .replace(/soulreap/i, "soul reap").replace(/treefeller/i, "tree feller");
      const name = raw.replace(/\b\w/g, char => char.toUpperCase());
      const roman = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"][level] || String(level);
      return `${name} ${roman}`;
    });
}

export function enhancementState(variantKey, enchantments) {
  if (!String(variantKey || "").startsWith("oxy2:")) return "unknown";
  return runeTags(variantKey, enchantments).length ? "runed" : "unruned";
}
