import { useEffect, useId, useRef, useState } from "react";
import { Check, ChevronDown } from "lucide-react";

// Identity-matched dropdown replacing native <select> where the OS-rendered
// option list (browser-blue hover, double focus ring) clashed with the site.
// Single highlight language: border shift on the trigger, emerald wash on
// hover/active option, check on the selected row. Full keyboard support.
export default function ListSelect({
  value,
  onChange,
  options = [],
  testid,
  ariaLabel,
  accent = "emerald",
  className = "",
}) {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const rootRef = useRef(null);
  const listRef = useRef(null);
  const buttonRef = useRef(null);
  const listId = useId();
  const selected = options.find((o) => o.value === value) || options[0] || null;

  const wash = accent === "amber"
    ? "bg-amber-500/10 text-amber-200"
    : accent === "indigo"
      ? "bg-indigo-500/10 text-indigo-200"
      : "bg-emerald-500/10 text-emerald-200";
  const checkColor = accent === "amber"
    ? "text-amber-300"
    : accent === "indigo"
      ? "text-indigo-300"
      : "text-emerald-300";
  const openBorder = accent === "amber"
    ? "border-amber-500/60"
    : accent === "indigo"
      ? "border-indigo-500/60"
      : "border-emerald-500/60";
  const chevronColor = accent === "amber"
    ? "text-amber-400"
    : accent === "indigo"
      ? "text-indigo-400"
      : "text-emerald-400";

  useEffect(() => {
    if (!open) return undefined;
    const onDown = (e) => {
      if (rootRef.current && !rootRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("touchstart", onDown);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("touchstart", onDown);
    };
  }, [open ]);

  useEffect(() => {
    if (open) {
      const idx = Math.max(0, options.findIndex((o) => o.value === value));
      setActive(idx);
    }
  }, [open, options, value]);

  useEffect(() => {
    if (!open || active < 0) return;
    listRef.current?.querySelector(`[data-idx="${active}"]`)?.scrollIntoView({ block: "nearest" });
  }, [open, active]);

  const choose = (optionValue) => {
    onChange(optionValue);
    setOpen(false);
    buttonRef.current?.focus();
  };

  const onTriggerKey = (e) => {
    if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      setOpen(true);
    }
  };

  const onListKey = (e) => {
    if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => Math.min(options.length - 1, a + 1)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => Math.max(0, a - 1)); }
    else if (e.key === "Home") { e.preventDefault(); setActive(0); }
    else if (e.key === "End") { e.preventDefault(); setActive(options.length - 1); }
    else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); if (options[active]) choose(options[active].value); }
    else if (e.key === "Escape") { e.preventDefault(); setOpen(false); buttonRef.current?.focus(); }
    else if (e.key === "Tab") { setOpen(false); }
  };

  return (
    <div ref={rootRef} className={`relative ${className}`}>
      <button
        ref={buttonRef}
        type="button"
        data-testid={testid}
        aria-label={ariaLabel}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        onClick={() => setOpen((o) => !o)}
        onKeyDown={onTriggerKey}
        className={`inline-flex w-full items-center justify-between gap-2 rounded-lg border bg-white/[0.03] px-4 py-2.5 font-mono text-xs uppercase tracking-wider outline-none transition-colors cursor-pointer ${
          open ? `${openBorder} text-white` : "border-white/10 text-white hover:border-white/30"
        }`}
      >
        <span className="truncate">{selected?.label ?? "—"}</span>
        <ChevronDown className={`h-3.5 w-3.5 shrink-0 text-zinc-500 transition-transform ${open ? `rotate-180 ${chevronColor}` : ""}`} />
      </button>
      {open && (
        <div
          ref={listRef}
          id={listId}
          role="listbox"
          aria-label={ariaLabel}
          tabIndex={-1}
          onKeyDown={onListKey}
          className="absolute z-30 mt-2 max-h-64 min-w-full overflow-y-auto overscroll-contain rounded-lg border border-white/10 bg-bg-deep shadow-2xl p-1"
        >
          {options.map((opt, idx) => {
            const isSelected = opt.value === value;
            const isActive = idx === active;
            return (
              <button
                key={opt.value}
                type="button"
                role="option"
                aria-selected={isSelected}
                data-idx={idx}
                data-testid={testid ? `${testid}-option-${opt.value || "all"}` : undefined}
                onMouseEnter={() => setActive(idx)}
                onClick={() => choose(opt.value)}
                className={`flex w-full items-center justify-between gap-2 rounded-md px-3 py-2 text-left font-mono text-xs uppercase tracking-wider transition-colors ${
                  isActive ? wash : "text-zinc-300"
                }`}
              >
                <span className="truncate">{opt.label}</span>
                {isSelected && <Check className={`h-3.5 w-3.5 shrink-0 ${checkColor}`} />}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}
